/* cppi::2f18d1680b1279075b4fc134d687327d09ee5f9a25f00255d5006a1c97f210d5 */
select business_date as date_, security_id, 'SP500_25' as strategy_id, weight_ndo as weight
                                  from (select * from (select *, ROW_NUMBER() OVER (PARTITION by business_date, id_vendor_security_ndo, id_cppib_index order by feed_version asc) as rn from market.cppib_market_index_constituents_mapped_rimes) where rn = 1)
                                  where business_date >= date '2025-06-18' and business_date <= date '2025-06-18' and weight_ndo>0 and id_cppib_index = 'SP500_25_GR_USD_0_0' and security_id is not null

/* cppi::fd83558f61009cf4731261cff2fd4cd2fcc704ea32af8afe2c0f486fa24278df */
